#include <bits/stdc++.h>
using namespace std;
long long score(int a,int b,int n,const vector<long long> & P){
    int c=n-a-b;
    long long x=6LL*P[a];
    long long y=4LL*(P[a+(2*b)]-P[a]);
    long long z=3LL*(P[a+(2*b)+(3*c)]-P[a+(2*b)]);
    return x+y+z;
}
void solve(){
    int n;
    cin >> n;
    int size =3*n;
    
    vector<long long> nums(size);
    
    for(int i=0;i<size;i++){
        cin>>nums[i];
    }
    sort(nums.rbegin(),nums.rend());
    vector<long long> prefix(size+1,0);
    for(int i=0;i<size;i++){
        prefix[i+1]=prefix[i]+nums[i];
    }
    long long ans=0;
    
    for(int a=0;a<=n;a++){
        int l=0;
        int r=n-a;
        
        while(r-l>2){
            int mid1=l+(r-l)/3;
            int mid2=r-(r-l)/3;
            
            if(score(a,mid1,n,prefix)<score(a,mid2,n,prefix)){
                l=mid1;
            }
            else{
                r=mid2;
            }
        }
        for(int b=l;b<=r;b++){
            long long curr= score(a,b,n,prefix);
            ans=max(ans,curr);
        }
        
    }
    cout<<ans<<"\n";
}
int main() {
	// your code goes here
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	int t;
	if(cin>>t){
	    while(t--){
	        solve();
	    }
	}
	return 0;

}
